};

my $owner    = $args->{owner}    or die "Missing required: owner";
my $repo     = $args->{repo}     or die "Missing required: repo";
my $title    = $args->{title}    or die "Missing required: title";
my $body     = $args->{body}     // '';
my $labels   = $args->{labels}   // undef;
my $assignees = $args->{assignees} // undef;

my %payload = (title => $title, body => $body);
$payload{labels}    = $labels    if $labels;
$payload{assignees} = $assignees if $assignees;

my $body_str = $main::json_pp_decoder->encode(\%payload);
my $res = _github_api("POST", "/repos/$owner/$repo/issues", $body_str);

if ($res->{success}) {
    my $issue = $res->{data};
    return {
        issue_number => $issue->{number},
        issue_url    => $issue->{html_url},
        state        => $issue->{state},
        title        => $issue->{title},
        created_at   => $issue->{created_at},
    };
}
die "GitHub API error: " . ($res->{reason} // "HTTP $res->{status}");

my $text = $args->{text} or die "Missing required parameter: text";
my $src = $args->{source} // 'auto';
my $tgt = $args->{target} // 'ru';
my $pair = $src eq 'auto' ? $tgt : "$src|$tgt";
my $e = _uri_escape_utf8($text);
my $url = "https://api.mymemory.translated.net/get?q=$e&langpair=$pair";
my $r = _safe_http_get_json($url);
die "HTTP error: $r->{status} - $r->{reason}" unless $r->{success};
my $d = $r->{data};
my $translated = $d->{responseData}{translatedText} // '';
my $detected   = $d->{responseData}{detectedLanguage} // $src;
my $match      = ($d->{responseData}{match} // 0) + 0;
return {
    original_text   => $text,
    translated_text => $translated,
    source_lang     => $detected,
    target_lang     => $tgt,
    match_quality   => $match,
};

